<?php
require_once __DIR__.'/../includes/functions.php'; require_login();
$user=current_user(); $uid=(int)$user['id'];
$totalLessons=(int)$pdo->query('SELECT COUNT(*) FROM lessons WHERE is_published=1')->fetchColumn();
$stmt=$pdo->prepare("SELECT COUNT(*) FROM user_progress WHERE user_id=? AND item_type='lesson'");$stmt->execute([$uid]);$completed=(int)$stmt->fetchColumn();
$stmt=$pdo->prepare('SELECT COUNT(*), COALESCE(ROUND(AVG(percentage)),0) FROM quiz_attempts WHERE user_id=?');$stmt->execute([$uid]);[$attempts,$average]=$stmt->fetch(PDO::FETCH_NUM);
$stmt=$pdo->prepare("SELECT l.id,l.title,l.level,l.description,l.estimated_minutes,up.completed_at FROM lessons l LEFT JOIN user_progress up ON up.item_id=l.id AND up.item_type='lesson' AND up.user_id=? WHERE l.is_published=1 ORDER BY l.sort_order,l.id LIMIT 4");$stmt->execute([$uid]);$lessons=$stmt->fetchAll();
$page_title='My learning';$active_page='dashboard';require __DIR__.'/../includes/header.php';
?>
<section class="dashboard-hero"><div class="container dashboard-welcome"><div><span class="eyebrow eyebrow-light">YOUR LEARNING SPACE</span><h1>Good to see you, <?= e($user['name']) ?>.</h1><p>Every word you learn brings you closer to confident Somali.</p></div><a class="btn btn-white" href="<?= url('pages/lessons.php') ?>">Continue learning →</a></div></section>
